From 1f6a0826b5fb9c36c871fd44b4a11568c472b36b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 23:39:37 +0100
Subject: [PATCH] kirigamiplasmastyle: follow application font changes

The Plasma theme for Kirigami read the application font only once, so
Kirigami.Theme.defaultFont kept the old family and size after the font
was changed until plasmashell restarted. Sync the fonts on each change.

BUG: 519494
---
 .../kirigamiplasmastyle/plasmatheme.cpp       | 49 ++++++++++++++++---
 .../kirigamiplasmastyle/plasmatheme.h         |  1 +
 2 files changed, 42 insertions(+), 8 deletions(-)

diff --git a/src/declarativeimports/kirigamiplasmastyle/plasmatheme.cpp b/src/declarativeimports/kirigamiplasmastyle/plasmatheme.cpp
index eb317484e..6cd1f26a0 100644
--- a/src/declarativeimports/kirigamiplasmastyle/plasmatheme.cpp
+++ b/src/declarativeimports/kirigamiplasmastyle/plasmatheme.cpp
@@ -19,6 +19,30 @@
 #include <KConfigGroup>
 #include <KIconColors>

+class FontWatcher : public QObject
+{
+public:
+    FontWatcher()
+    {
+        qGuiApp->installEventFilter(this);
+    }
+
+    QList<PlasmaTheme *> watchers;
+
+protected:
+    bool eventFilter(QObject *obj, QEvent *event) override
+    {
+        if (obj == qGuiApp && event->type() == QEvent::ApplicationFontChange) {
+            for (auto watcher : std::as_const(watchers)) {
+                watcher->syncFonts();
+            }
+        }
+        return false;
+    }
+};
+
+Q_GLOBAL_STATIC(FontWatcher, s_fontWatcher)
+
 PlasmaTheme::PlasmaTheme(QObject *parent)
     : PlatformTheme(parent)
 {
@@ -36,6 +60,23 @@ PlasmaTheme::PlasmaTheme(QObject *parent)
         });
     }

+    syncFonts();
+
+    syncWindow();
+    syncColors();
+    connect(&m_theme, &Plasma::Theme::themeChanged, this, &PlasmaTheme::syncColors);
+    s_fontWatcher->watchers.append(this);
+}
+
+PlasmaTheme::~PlasmaTheme()
+{
+    if (!s_fontWatcher.isDestroyed()) {
+        s_fontWatcher->watchers.removeOne(this);
+    }
+}
+
+void PlasmaTheme::syncFonts()
+{
     setDefaultFont(qGuiApp->font());

     KSharedConfigPtr ptr = KSharedConfig::openConfig();
@@ -52,14 +93,6 @@ PlasmaTheme::PlasmaTheme(QObject *parent)
 #endif
         return smallFont;
     }()));
-
-    syncWindow();
-    syncColors();
-    connect(&m_theme, &Plasma::Theme::themeChanged, this, &PlasmaTheme::syncColors);
-}
-
-PlasmaTheme::~PlasmaTheme()
-{
 }

 QIcon PlasmaTheme::iconFromTheme(const QString &name, const QColor &customColor)
diff --git a/src/declarativeimports/kirigamiplasmastyle/plasmatheme.h b/src/declarativeimports/kirigamiplasmastyle/plasmatheme.h
