--- a/src/declarativeimports/kirigamiplasmastyle/plasmatheme.h
+++ b/src/declarativeimports/kirigamiplasmastyle/plasmatheme.h
@@ -30,6 +30,7 @@ public:

     void syncWindow();
     void syncColors();
+    void syncFonts();
     void syncFrameContrast();

 protected:
